#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <string>
#include <vector>

[[nodiscard]] std::optional<std::ptrdiff_t> pivot_index(std::span<const int> weights) {
  std::int64_t total = 0;
  for (const int w : weights) total += w;
  std::int64_t left = 0;
  for (std::ptrdiff_t i = 0; i < std::ssize(weights); ++i) {
    const std::int64_t right = total - left - weights[i];
    if (left == right) return i;
    left += weights[i];
  }
  return std::nullopt;
}

[[nodiscard]] std::string show(const std::optional<std::ptrdiff_t>& index) {
  return index ? std::format("{}", *index) : "no value";
}

int main() {
  const std::vector<int> a{1, 7, 3, 6, 5, 6};
  const std::vector<int> b{1, 2, 3};
  const std::vector<int> c{2, 1, -1};
  std::cout << std::format("{} {} {} {}\n", show(pivot_index(a)), show(pivot_index(b)), show(pivot_index(c)),
                           show(pivot_index({})));
}

#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <optional>
#include <string>
#include <utility>
#include <vector>

struct Node {
  int value = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int value, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(value, std::move(left), std::move(right));
}

[[nodiscard]] std::optional<int> kth_smallest(const Node* root, std::int64_t k) {
  if (k < 1) return std::nullopt;
  std::vector<const Node*> stack;  // ancestors still waiting for their right subtree
  const Node* current = root;
  while (current != nullptr || !stack.empty()) {
    while (current != nullptr) {
      stack.push_back(current);
      current = current->left.get();
    }
    current = stack.back();
    stack.pop_back();
    --k;
    if (k == 0) return current->value;
    current = current->right.get();
  }
  return std::nullopt;  // k was larger than the number of nodes
}

[[nodiscard]] std::string show(const std::optional<int>& value) {
  return value ? std::format("{}", *value) : "no value";
}

int main() {
  const std::unique_ptr<Node> tree =
      node(6, node(2, node(1), node(4, node(3), nullptr)), node(8, node(7), node(9)));
  for (const std::int64_t k : {1, 4, 8, 9, 0}) {
    std::cout << std::format("k={}: {}\n", k, show(kth_smallest(tree.get(), k)));
  }
  std::cout << "empty tree: " << show(kth_smallest(nullptr, 1)) << '\n';
}
